"""Robot pets from Chapter 7, now with the new speak() feature."""


class RobotPet:
    def __init__(self, name, battery=100, mood="neutral"):
        self.name = name
        self.battery = battery
        self.mood = mood

    def speak(self):
        if self.battery < 20:
            return f"{self.name} needs to recharge."
        if self.mood == "happy":
            return f"{self.name} is happy to see you!"
        return f"Hello, I am {self.name}."


class RobotCat(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} is too tired to purr."
        if self.mood == "happy":
            return f"Purr... {self.name} is a happy kitty!"
        return f"Meow! I am {self.name}."


class RobotBird(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} says the battery is low."
        if self.mood == "happy":
            return f"{self.name} sings: what a lovely day!"
        return f"Chirp chirp! I am {self.name}."


class RobotDog(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} needs a charge."
        if self.mood == "happy":
            return f"Best day ever! {self.name} is wagging its tail!"
        return f"Woof! I am {self.name}."
